import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

.visible .entry matmul_kernel(
    .param .u64 param_A,
    .param .u64 param_B,
    .param .u64 param_C,
    .param .u32 param_n
)
{
    .reg .b32 %r_tx, %r_ty, %r_bx, %r_by;
    .reg .b32 %r_row, %r_col, %r_n, %r_kt, %r_k;
    .reg .b32 %r_idx, %r_tileidx, %r_saddr;
    .reg .b32 %r_sA, %r_sB;
    .reg .b64 %rd_A, %rd_B, %rd_C, %rd_off, %rd_addr;
    .reg .f32 %f_acc, %f_a, %f_b;
    .reg .pred %p1, %p2;

    .shared .align 16 .b8 sA[1024];
    .shared .align 16 .b8 sB[1024];

    mov.u32 %r_tx, %tid.x;
    mov.u32 %r_ty, %tid.y;
    mov.u32 %r_bx, %ctaid.x;
    mov.u32 %r_by, %ctaid.y;

    ld.param.u64 %rd_A, [param_A];
    ld.param.u64 %rd_B, [param_B];
    ld.param.u64 %rd_C, [param_C];
    ld.param.u32 %r_n, [param_n];

    shl.b32 %r_bx, %r_bx, 4;
    shl.b32 %r_by, %r_by, 4;
    add.u32 %r_row, %r_by, %r_ty;
    add.u32 %r_col, %r_bx, %r_tx;

    mov.u32 %r_sA, sA;
    mov.u32 %r_sB, sB;

    mov.f32 %f_acc, 0f00000000;
    mov.u32 %r_kt, 0;

$mm_outer:
    setp.ge.u32 %p1, %r_kt, %r_n;
    @%p1 bra $mm_store;

    // Load tile of A: sA[ty*16+tx] = A[row*n + kt + tx] (zero if out of range)
    add.u32 %r_idx, %r_kt, %r_tx;
    setp.lt.u32 %p1, %r_row, %r_n;
    setp.lt.u32 %p2, %r_idx, %r_n;
    and.pred %p1, %p1, %p2;
    mov.f32 %f_a, 0f00000000;
    mul.lo.u32 %r_idx, %r_row, %r_n;
    add.u32 %r_idx, %r_idx, %r_kt;
    add.u32 %r_idx, %r_idx, %r_tx;
    mul.wide.u32 %rd_off, %r_idx, 4;
    add.u64 %rd_addr, %rd_A, %rd_off;
    @%p1 ld.global.f32 %f_a, [%rd_addr];
    shl.b32 %r_tileidx, %r_ty, 4;
    add.u32 %r_tileidx, %r_tileidx, %r_tx;
    mul.lo.u32 %r_saddr, %r_tileidx, 4;
    add.u32 %r_saddr, %r_saddr, %r_sA;
    st.shared.f32 [%r_saddr], %f_a;

    // Load tile of B: sB[ty*16+tx] = B[(kt+ty)*n + col] (zero if out of range)
    add.u32 %r_idx, %r_kt, %r_ty;
    setp.lt.u32 %p1, %r_idx, %r_n;
    setp.lt.u32 %p2, %r_col, %r_n;
    and.pred %p1, %p1, %p2;
    mov.f32 %f_b, 0f00000000;
    mul.lo.u32 %r_idx, %r_idx, %r_n;
    add.u32 %r_idx, %r_idx, %r_col;
    mul.wide.u32 %rd_off, %r_idx, 4;
    add.u64 %rd_addr, %rd_B, %rd_off;
    @%p1 ld.global.f32 %f_b, [%rd_addr];
    shl.b32 %r_tileidx, %r_ty, 4;
    add.u32 %r_tileidx, %r_tileidx, %r_tx;
    mul.lo.u32 %r_saddr, %r_tileidx, 4;
    add.u32 %r_saddr, %r_saddr, %r_sB;
    st.shared.f32 [%r_saddr], %f_b;

    bar.sync 0;

    mov.u32 %r_k, 0;
$mm_inner:
    setp.ge.u32 %p1, %r_k, 16;
    @%p1 bra $mm_inner_done;

    shl.b32 %r_tileidx, %r_ty, 4;
    add.u32 %r_tileidx, %r_tileidx, %r_k;
    mul.lo.u32 %r_saddr, %r_tileidx, 4;
    add.u32 %r_saddr, %r_saddr, %r_sA;
    ld.shared.f32 %f_a, [%r_saddr];

    shl.b32 %r_tileidx, %r_k, 4;
    add.u32 %r_tileidx, %r_tileidx, %r_tx;
    mul.lo.u32 %r_saddr, %r_tileidx, 4;
    add.u32 %r_saddr, %r_saddr, %r_sB;
    ld.shared.f32 %f_b, [%r_saddr];

    fma.rn.f32 %f_acc, %f_a, %f_b, %f_acc;

    add.u32 %r_k, %r_k, 1;
    bra $mm_inner;

$mm_inner_done:
    bar.sync 0;
    add.u32 %r_kt, %r_kt, 16;
    bra $mm_outer;

$mm_store:
    setp.lt.u32 %p1, %r_row, %r_n;
    setp.lt.u32 %p2, %r_col, %r_n;
    and.pred %p1, %p1, %p2;
    @!%p1 bra $mm_exit;
    mul.lo.u32 %r_idx, %r_row, %r_n;
    add.u32 %r_idx, %r_idx, %r_col;
    mul.wide.u32 %rd_off, %r_idx, 4;
    add.u64 %rd_addr, %rd_C, %rd_off;
    st.global.f32 [%rd_addr], %f_acc;

$mm_exit:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("matmul_kernel")

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float32 and B.dtype == torch.float32
        assert A.dim() == 2 and B.dim() == 2
        assert A.shape[1] == B.shape[0]
        assert A.is_contiguous() and B.is_contiguous()
        M, K = A.shape
        _, N = B.shape
        assert M == K == N  # Reference uses a single square N x N matmul.

        C = torch.empty((M, N), dtype=A.dtype, device=A.device)

        module = _get_ptx_module()
        tile = 16
        grid_x = (N + tile - 1) // tile
        grid_y = (M + tile - 1) // tile
        module.launch(
            "matmul_kernel",
            grid=(grid_x, grid_y, 1),
            block=(tile, tile, 1),
            arguments=[A, B, C, u32(N)],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return C

